/**
 * Helper: execute a traverser either sequentially or, when compiled with OpenMP,
 * in parallel over its top-most dimension.
 *
 * The loop nest itself is still expressed via Noarr traversers:
 *   - outer range-based loop iterates traverser "slices"
 *   - inner .for_each visits the remaining dimensions
 *
 * For a 1D structure (only 'i'), each sub-traverser represents exactly
 * one scalar element and .for_each calls the body once.
 */
template<class Traverser, class Func>
inline void trav_for_each_parallel(const Traverser &trav, const Func &body) {
#ifdef _OPENMP
	// Parallelize over the outer-most dimension of the traverser.
	// Each sub_trav covers a disjoint slice of the data.
	#pragma omp parallel for schedule(static)
	for (auto sub_trav : trav) {
		sub_trav.for_each(body);
	}
#else
	// Fallback: plain sequential traversal
	trav.for_each(body);
#endif
}


// initialization function
void init_array(auto A, auto B) {
	using namespace noarr;

	// spatial problem size (constant for the whole initialization)
	auto n = A | get_length<'i'>();

	auto trav = traverser(A, B);

	trav_for_each_parallel(trav, [=](auto state) {
		auto i = get_index<'i'>(state);

		A[state] = (static_cast<num_t>(i) + static_cast<num_t>(2)) / static_cast<num_t>(n);
		B[state] = (static_cast<num_t>(i) + static_cast<num_t>(3)) / static_cast<num_t>(n);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size (constant over all time steps)
	auto n = A | get_length<'i'>();

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);
	auto time_trav  = traverser(time_struct);

	// view selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Prebuild traversers for the two sweeps on the interior.
	// These are reused for each time step.
	auto trav_B_from_A = traverser(B, A).order(interior);
	auto trav_A_from_B = traverser(A, B).order(interior);

	// Constant factor used in all updates
	constexpr num_t one_third = static_cast<num_t>(0.33333);

	// Bodies of the two spatial sweeps, expressed as lambdas taking a Noarr state.
	// Using lambdas allows reuse across time steps and between parallel/sequential variants.
	auto sweep_B_from_A = [=](auto state) {
		// state has index 'i' in [1, n-2]
		auto left  = state - noarr::idx<'i'>(1); // i-1
		auto right = state + noarr::idx<'i'>(1); // i+1

		B[state] = one_third * (A[left] + A[state] + A[right]);
	};

	auto sweep_A_from_B = [=](auto state) {
		auto left  = state - noarr::idx<'i'>(1); // i-1
		auto right = state + noarr::idx<'i'>(1); // i+1

		A[state] = one_third * (B[left] + B[state] + B[right]);
	};

	#pragma scop
	// Time loop: strictly sequential in t, but each spatial sweep is parallelized
	// over the 1D domain using trav_for_each_parallel.
	time_trav.for_each([&](auto /*t_state*/) {
		// first sweep: update B from A
		trav_for_each_parallel(trav_B_from_A, sweep_B_from_A);

		// second sweep: update A from B
		trav_for_each_parallel(trav_A_from_B, sweep_A_from_B);
	});
	#pragma endscop
