//
// Optimizations over the original version:
//
// 1. Hoist constant factors (Jacobi coefficient and spatial length) out of
//    the inner loops so they are not recomputed per element.
// 2. Use a Noarr proto-structure composed of:
//       - slice<'i'>(1, n - 2)                   : select interior points
//       - into_blocks_static<'i', '!', 'I', 'j'> : tile the 1D domain into
//                                                 blocks of fixed size
//       - hoist<'I'>                             : make the block index
//                                                 the outermost loop
//    and apply it through traverser(...).order(...).
//
//    This changes the *loop nest shape* (block-major iteration) while
//    preserving the *logical indices* used in the kernel. Because we use
//    order(), the states passed to the kernel still contain only the
//    original 'i' dimension, so the neighbor accesses (i-1, i, i+1) remain
//    valid and contiguous in memory. The tiling improves cache behavior
//    and makes the iteration space friendlier for auto-vectorization,
//    especially on long vectors.
//
// 3. Preserve the original double sweep per time step (A->B and B->A),
//    so the numerical behavior is unchanged.
//
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;
	using noarr::lit;

	// Spatial problem size
	auto n = A | get_length<'i'>();

	// Structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// View selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Block size for spatial tiling. This is a tuning parameter; 256 works
	// well on typical x86_64 caches and SIMD widths. It is encoded as a
	// static value (lit<...>) so that the compiler can fully optimize the
	// block logic.
	constexpr auto block_size = lit<256>;

	// Build a proto-structure that:
	//   - restricts to interior indices 'i' in [1, n-2]
	//   - splits 'i' into blocks of size block_size (major dim 'I',
	//     minor dim 'j', and a small tuple-like border flag '!')
	//   - hoists 'I' to the outermost traversal dimension
	//
	// NOTE: This proto-structure is *only* used to control the traverser
	//       loop nest via .order().  The state seen inside the lambda is
	//       still expressed in the original coordinates (only 'i'), so
	//       neighbor accesses using state +/- idx<'i'>(1) remain correct.
	auto blocked_interior =
		interior
		^ noarr::into_blocks_static<'i', '!', 'I', 'j'>(block_size)
		^ noarr::hoist<'I'>();

	// Jacobi coefficient: hoisted out of the inner loops
	const num_t coeff = static_cast<num_t>(0.33333);

	#pragma scop
	traverser(time_struct).for_each([=](auto /*t_state*/) {
		// First sweep: update B from A
		//
		// Traversal is tiled and block-major according to blocked_interior,
		// but each state still exposes only the original 'i' index.
		traverser(B, A).order(blocked_interior).for_each([=](auto state) {
			auto left  = state - noarr::idx<'i'>(1);
			auto right = state + noarr::idx<'i'>(1);

			B[state] = coeff * (A[left] + A[state] + A[right]);
		});

		// Second sweep: update A from B
		traverser(A, B).order(blocked_interior).for_each([=](auto state) {
			auto left  = state - noarr::idx<'i'>(1);
			auto right = state + noarr::idx<'i'>(1);

			A[state] = coeff * (B[left] + B[state] + B[right]);
		});
	});
	#pragma endscop
}

