// include benchmark-specific definitions
#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();

struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// initialization function
void init_array(auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	auto n = A | get_length<'i'>();
	const num_t inv_n = num_t(1) / static_cast<num_t>(n);

	// simple element-wise initialization
	traverser(A, B).for_each([&](auto state) {
		auto i = get_index<'i'>(state);

		A[state] = (static_cast<num_t>(i) + static_cast<num_t>(2)) * inv_n;
		B[state] = (static_cast<num_t>(i) + static_cast<num_t>(3)) * inv_n;
	});
}

// computation kernel
// Optimized: we fuse the two spatial sweeps of each time-step into a single
// pass over the spatial dimension and keep the necessary B values in a
// small sliding window of registers. This avoids re-reading B from memory
// in a second pass and improves cache and memory bandwidth efficiency while
// preserving the original Jacobi semantics.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	auto n = A | get_length<'i'>();

	// for very small problems there are no interior points; nothing to do
	if (n < 3 || tsteps <= 0)
		return;

	// structure used only to iterate over time steps
	auto time_struct =
		noarr::scalar<num_t>() ^ noarr::vector<'t'>(static_cast<std::size_t>(tsteps));

	// view selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Jacobi weight
	const num_t weight = static_cast<num_t>(0.33333);

	#pragma scop
	traverser(time_struct).for_each([&](auto /*t_state*/) {
		// ---------------------------
		// FUSED TWO-SWEEP JACOBI STEP
		// ---------------------------
		//
		// Original algorithm per time step:
		//
		//   for i in 1..n-2:
		//     B[i] = w * (A[i-1] + A[i] + A[i+1]);
		//   for i in 1..n-2:
		//     A[i] = w * (B[i-1] + B[i] + B[i+1]);
		//
		// Our optimized version performs a *single* pass over the spatial
		// dimension. For each interior index i we:
		//   1) compute B[i] from A[i-1],A[i],A[i+1]
		//   2) (for i >= 2) compute A[i-1] from B[i-2],B[i-1],B[i]
		//
		// This is possible because when computing A[i-1] we only need B up to
		// index i, which have already been computed in the same pass.
		//
		// We keep a sliding window of three consecutive B values:
		//   b_left   = B[i-2]
		//   b_center = B[i-1]
		//   Bi       = B[i]    (computed in current iteration)
		//
		// and update it as we move forward through i. Boundary B[0] and B[n-1]
		// are read once per time-step and never updated, exactly as in the
		// original code.

		// boundary B values (do not change during this time step)
		const auto b_left_state  = noarr::idx<'i'>(0);
		const auto b_right_state = noarr::idx<'i'>(n - 1);

		num_t b_left     = B[b_left_state]; // B[0]
		num_t b_center   = num_t(0);        // will become B[1]
		bool  have_center = false;          // indicates that b_center is valid

		// single pass over i in [1, n-2]
		traverser(B, A).order(interior).for_each([&](auto state) {
			// --- first sweep part: B update from A ---

			// neighbors for A stencil
			auto left_state  = state - noarr::idx<'i'>(1); // i-1
			auto right_state = state + noarr::idx<'i'>(1); // i+1

			const num_t a_im1 = A[left_state];
			const num_t a_i   = A[state];
			const num_t a_ip1 = A[right_state];

			const num_t Bi = weight * (a_im1 + a_i + a_ip1);
			B[state] = Bi; // B[i]

			// --- second sweep part: A update from B (fused) ---
			//
			// For i >= 2 we now have:
			//   b_left   = B[i-2]
			//   b_center = B[i-1]
			//   Bi       = B[i]
			// so we can compute:
			//   A[i-1] = w * (B[i-2] + B[i-1] + B[i])

			if (have_center) {
				// i >= 2: update A[i-1]
				auto a_target_state = left_state; // corresponds to index i-1
				A[a_target_state] = weight * (b_left + b_center + Bi);

				// shift window:
				b_left   = b_center; // B[i-1]
				b_center = Bi;       // B[i]
			} else {
				// i == 1: we only have B[0] and B[1]; still missing B[2],
				// so we cannot update any A element yet. Initialize
				// b_center and wait for the next iteration.
				b_center    = Bi;   // B[1]
				have_center = true;
			}
		});

		// After the loop the sliding window holds:
		//   b_left   = B[n-3]
		//   b_center = B[n-2]
		// We still need to compute A[n-2] using:
		//   B[n-3], B[n-2], B[n-1]
		if (have_center) { // there was at least one interior point
			const auto a_last_state = noarr::idx<'i'>(n - 2);
			const num_t b_right = B[b_right_state]; // B[n-1], boundary

			A[a_last_state] = weight * (b_left + b_center + b_right);
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size and number of time steps
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set the length of the spatial dimension
	auto set_lengths = noarr::set_length<'i'>(n);

	// allocate bags for A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_1d(static_cast<int>(tsteps), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to inhibit dead-code elimination in benchmarks)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

